package edu.csc223.planner;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.time.LocalDate;
class Milestone10Test {
    ReleasePlanner p(){return ReleaseDemo.fixture();}
    Assignment a(int id){return new Assignment(id,223,10,"Same",LocalDate.of(2026,12,14),5,Assignment.Status.PENDING);}
    @Test void heapBulkEmptyAndSingleton(){var h=new BinaryHeap<Integer>(Comparator.naturalOrder(),List.of());assertNull(h.peek());h=new BinaryHeap<>(Comparator.naturalOrder(),List.of(8));assertEquals(8,h.removeRoot());assertNull(h.removeRoot());}
    @Test void heapBulkProtectsSourceAndRejectsNull(){var values=new ArrayList<>(List.of(4,1,3));var old=List.copyOf(values);var h=new BinaryHeap<>(Comparator.naturalOrder(),values);assertEquals(old,values);values.clear();assertEquals(3,h.size());assertThrows(NullPointerException.class,()->new BinaryHeap<Integer>(Comparator.naturalOrder(),Arrays.asList(1,null)));}
    @Test void heapAllDistributionsAgainstIndependentSort(){for(int n:new int[]{1,16,64,256,1024})for(String c:List.of("ordered","reverse","random")){var values=ReleaseBenchmark.data(n,c);var expected=new ArrayList<>(values);expected.sort(PrioritySchedule.ORDER);var h=new BinaryHeap<>(PrioritySchedule.ORDER,values);var b=HeapBuildBaseline.build(PrioritySchedule.ORDER,values);for(var e:expected){assertEquals(e,h.removeRoot());assertEquals(e,b.removeRoot());}}}
    @Test void bulkComparisonBound(){var values=ReleaseBenchmark.data(4096,"reverse");var count=new ReleaseBenchmark.Counted();var heap=new BinaryHeap<>(count,values);assertTrue(count.count<2L*values.size());assertTrue(heap.isValidHeap());}
    @Test void fifoIdReuseDoesNotStartReplacement(){var p=PlannerPriorityDemo.planner();p.addAssignment(PlannerPriorityDemo.item(1,3,19));var q=new StudyWorkflow(p);q.enqueueAssignment(1);p.removeById(1);p.addAssignment(PlannerPriorityDemo.item(1,3,19));assertTrue(q.inspectNext().isEmpty());var result=q.startNext();assertTrue(result.started().isEmpty());assertEquals(1,result.discarded());assertEquals(Assignment.Status.PENDING,p.findById(1).status());}
    @Test void fifoEditsPreserveGeneration(){var p=PlannerPriorityDemo.planner();p.addAssignment(PlannerPriorityDemo.item(1,3,19));var q=new StudyWorkflow(p);q.enqueueAssignment(1);p.updatePriority(1,5);assertEquals(5,q.startNext().started().orElseThrow().priority());}
    @Test void titleFilterAndSortAreCurrent(){var p=p();assertEquals(List.of(2,3),p.searchTitle("PLANNER").stream().map(Assignment::id).toList());assertTrue(p.searchTitle("missing").isEmpty());assertEquals(4,p.filter(223,Assignment.Status.PENDING).size());assertTrue(p.filter(208,null).isEmpty());assertArrayEquals(new Integer[]{1,2,4,3},Arrays.stream(p.ordered(ReleasePlanner.Ordering.TITLE)).map(Assignment::id).toArray(Integer[]::new));assertThrows(IllegalArgumentException.class,()->p.searchTitle(" "));assertThrows(IllegalArgumentException.class,()->p.filter(999,null));}
    @Test void hierarchyIncludesEmptyParentsExactlyOnce(){var p=p();var h=p.hierarchy();assertEquals(2,h.size());assertEquals(2,h.get(0).modules().size());assertTrue(h.get(1).modules().isEmpty());assertTrue(h.get(0).modules().get(1).assignments().isEmpty());var ids=h.stream().flatMap(c->c.modules().stream()).flatMap(m->m.assignments().stream()).map(Assignment::id).toList();assertEquals(List.of(1,2,3,4),ids);assertThrows(UnsupportedOperationException.class,()->h.clear());}
    @Test void courseModuleLifecycleGuardsReferences(){var p=p();assertThrows(IllegalArgumentException.class,()->p.removeCourse(223));assertThrows(IllegalArgumentException.class,()->p.removeModule(10));p.renameCourse(223,"Renamed");p.retitleModule(10,"Release");p.removeModule(11);p.removeCourse(208);assertEquals("Renamed",p.hierarchy().get(0).course().name());assertEquals("Release",p.hierarchy().get(0).modules().get(0).module().title());assertTrue(p.validate().valid());}
    @Test void strictCycleDuplicateMissingPreserveState(){var p=p();var before=p.snapshot();var path=p.path(1,3);assertThrows(IllegalArgumentException.class,()->p.addPrerequisite(3,1));assertThrows(IllegalArgumentException.class,()->p.addPrerequisite(1,2));assertThrows(IllegalArgumentException.class,()->p.addPrerequisite(1,1));assertThrows(NoSuchElementException.class,()->p.addPrerequisite(1,99));assertArrayEquals(before,p.snapshot());assertEquals(path,p.path(1,3));assertTrue(p.validate().valid());}
    @Test void recommendationsRespectEveryKeyAndBlockers(){var p=p();assertEquals(4,p.recommend().orElseThrow().id());p.complete(1);assertEquals(2,p.recommend().orElseThrow().id());p.add(a(9));p.add(a(8));p.complete(2);assertEquals(8,p.recommend().orElseThrow().id());p.update(9,a(9).rescheduled(LocalDate.of(2026,12,13)));assertEquals(9,p.recommend().orElseThrow().id());}
    @Test void allAncestorsReported(){var p=p();assertEquals(Set.of(1,2),p.blockers(3));p.complete(1);assertEquals(Set.of(2),p.blockers(3));assertTrue(p.blockers(4).isEmpty());assertEquals(List.of(1,2,3),p.path(1,3));assertTrue(p.path(1,4).isEmpty());}
    @Test void strictFifoEligibilityAndExternalChange(){var p=p();assertThrows(IllegalArgumentException.class,()->p.enqueue(2));p.enqueue(1);p.enqueue(4);p.complete(1);assertEquals(4,p.startFifo().started().orElseThrow().id());assertTrue(p.startFifo().started().isEmpty());assertTrue(p.validate().valid());}
    @Test void fifoRechecksNewPrerequisite(){var p=p();p.enqueue(4);p.addPrerequisite(1,4);assertTrue(p.peekFifo().isEmpty());assertEquals(1,p.startFifo().discarded());p.complete(1);p.enqueue(4);assertEquals(4,p.startFifo().started().orElseThrow().id());}
    @Test void startAndCompleteCannotBypassDependencies(){var p=p();assertThrows(IllegalArgumentException.class,()->p.complete(2));assertThrows(IllegalArgumentException.class,()->p.update(2,p.find(2).withStatus(Assignment.Status.COMPLETE)));assertEquals(4,p.startRecommended().orElseThrow().id());assertThrows(IllegalArgumentException.class,()->p.addPrerequisite(1,4));p.complete(4);assertThrows(IllegalArgumentException.class,()->p.complete(4));assertTrue(p.validate().valid());}
    @Test void strictRemovalRequiresConstraintDecision(){var p=p();assertThrows(IllegalArgumentException.class,()->p.remove(1));p.removePrerequisite(1,2);p.remove(1);assertFalse(p.binaryFind(1).isPresent());assertTrue(p.isEligible(2));assertTrue(p.validate().valid());}
    @Test void updateSynchronizesViewsWithoutReordering(){var p=p();var revised=new Assignment(2,223,10,"Changed",LocalDate.of(2026,12,12),1,Assignment.Status.PENDING);p.update(2,revised);assertSame(revised,p.find(2));assertSame(revised,p.idRange(2,2).get(0));assertSame(revised,p.binaryFind(2).orElseThrow());assertSame(revised,p.hierarchy().get(0).modules().get(0).assignments().get(1));assertEquals(List.of(1,2,3),p.path(1,3));assertTrue(p.validate().valid());}
    @Test void emptyReleaseAndInvalidInput(){var p=new ReleasePlanner();assertTrue(p.recommend().isEmpty());assertTrue(p.startRecommended().isEmpty());assertTrue(p.startFifo().started().isEmpty());assertTrue(p.hierarchy().isEmpty());assertTrue(p.validate().valid());assertThrows(IllegalArgumentException.class,()->p.add(null));assertThrows(IllegalArgumentException.class,()->p.find(0));}
    @Test void releaseEndToEnd(){var p=p();p.enqueue(1);p.enqueue(4);assertEquals(1,p.startFifo().started().orElseThrow().id());p.complete(1);assertEquals(2,p.startRecommended().orElseThrow().id());p.complete(2);assertEquals(3,p.startRecommended().orElseThrow().id());p.complete(3);assertEquals(4,p.startFifo().started().orElseThrow().id());p.complete(4);assertEquals(0,p.countPending().pendingCount());assertTrue(p.recommend().isEmpty());p.remove(3);assertTrue(p.path(1,2).contains(2));assertTrue(p.validate().valid());}
    @Test void releaseVersion(){assertEquals("v1.0.0",ReleasePlanner.VERSION);}
}
